function blank(){return{status:"home",hostId:null,players:{},settings:settingsFor(selectedMode),deck:[],roundIndex:-1,cycle:0,currentRound:null,options:[],selections:{},locked:false,winnerId:null,correctAnswerId:null,roundStartedAt:0,matchStartedAt:0,endsAt:0,matchId:"",teamScores:{A:0,B:0,coop:0},finishReason:"",awards:[],spectators:0}}
