function buildManagerCards(){const out=[];for(const m of Object.values(M)){for(let i=0;i<m.clubs.length;i++)for(let j=i+1;j<m.clubs.length;j++){const A=m.clubs[i],B=m.clubs[j];if(D.teams[A]&&D.teams[B])out.push({id:`mgr-${m.id}-${A}-${B}`,kind:"manager",teamA:A,teamB:B,answer:m.id})}}return out}
function playerRound(id){const c=D.cards.find(x=>x.id===id);return c?{id:c.id,kind:"player",teamA:c.teamA,teamB:c.teamB,answer:c.answer}:null}
function makeDeck(content){const cfg=mode(),poolId=cfg.pool,allowed=poolId&&V.pools?.[poolId]?new Set(V.pools[poolId]):null,rand=cfg.daily?rng(new Date().toISOString().slice(0,10)+":"+cfg.id):Math.random;const allow=c=>!allowed||(allowed.has(c.teamA)&&allowed.has(c.teamB));const p=shuf(D.cards.filter(allow),rand).map(c=>({kind:"player",id:c.id})),m=shuf(managerCards.filter(allow),rand).map(c=>({kind:"manager",id:c.id}));if(content==="player")return p;if(content==="manager")return m;const out=[];let pi=0,mi=0;while(pi<p.length||mi<m.length){if(pi<p.length)out.push(p[pi++]);if(pi<p.length)out.push(p[pi++]);if(mi<m.length)out.push(m[mi++])}return out.length?out:[...p,...m]}
function resolveDeckItem(x){if(!x)return null;if(x.kind==="player")return playerRound(x.id);return managerCards.find(c=>c.id===x.id)||null}
function entity(kind,id){return kind==="manager"?M[id]:D.players[id]}
