function fromKey(k){const [t,id]=String(k||"").split(":");return{kind:t==="m"?"manager":"player",id}}
function buildOptions(r,count=S.settings.optionCount){count=[4,6,8].includes(+count)?+count:6;const pool=r.kind==="manager"?Object.values(M):Object.values(D.players),answer=entity(r.kind,r.answer),rand=rng(`${S.matchId}:${r.id}:${count}:${S.cycle}`),safe=pool.filter(p=>p.id!==r.answer&&!(p.clubs.includes(r.teamA)&&p.clubs.includes(r.teamB))),near=shuf(safe.filter(p=>p.clubs.includes(r.teamA)||p.clubs.includes(r.teamB)),rand),far=shuf(safe.filter(p=>!p.clubs.includes(r.teamA)&&!p.clubs.includes(r.teamB)),rand),pick=[];for(const p of [...near,...far]){if(pick.length>=count-1)break;if(!pick.some(x=>x.id===p.id))pick.push(p)}return shuf([answer,...pick],rand).slice(0,count).map(p=>key(r.kind,p.id))}
function competitors(){return Object.values(S.players).filter(p=>p.active!==false&&!p.spectator)}function eligible(){return competitors().filter(p=>!p.eliminated)}function activeCount(){return competitors().length}
function snap(){return{status:S.status,hostId:S.hostId,players:S.players,settings:S.settings,deck:S.deck,roundIndex:S.roundIndex,cycle:S.cycle,currentRound:S.currentRound?{id:S.currentRound.id,kind:S.currentRound.kind,teamA:S.currentRound.teamA,teamB:S.currentRound.teamB}:null,options:S.options,selections:S.selections,locked:S.locked,winnerId:S.winnerId,correctAnswerId:S.correctAnswerId,roundStartedAt:S.roundStartedAt,matchStartedAt:S.matchStartedAt,endsAt:S.endsAt,matchId:S.matchId,teamScores:S.teamScores,finishReason:S.finishReason,awards:S.awards,spectators:Object.values(S.players).filter(p=>p.spectator&&p.active!==false).length}}
