function syncProfileUI(){U.profileNameInput.value=profile.username||"";U.profileNameText.textContent=profile.username||"Oyuncu";U.profileAvatar.textContent=initials(profile.username||"QF");U.profileRatingText.textContent=Math.round(profile.rating);U.profileLevelText.textContent=profile.level;U.profileSetup.classList.toggle("saved",!!profile.username)}
function renderModeTabs(group="competitive"){document.querySelectorAll(".mode-tab").forEach(b=>b.classList.toggle("active",b.dataset.group===group));const arr=Object.values(MODES).filter(m=>m.group===group);U.modeGrid.innerHTML=arr.map(m=>`<button class="mode-card ${m.id===selectedMode?"selected":""}" data-mode="${m.id}"><span class="mode-icon">${m.icon}</span>${m.rated?'<span class="rated-flag">RANKED</span>':""}<h3>${esc(m.name)}</h3><p>${esc(m.desc)}</p><div class="mode-meta"><span>${m.timeLimit?Math.round(m.timeLimit/60)+" DK":m.roundCount+" KART"}</span><span>${m.optionCount} SEÇENEK</span><span>${m.content==="manager"?"HOCA":m.content==="mixed"?"KARMA":"OYUNCU"}</span></div></button>`).join("");U.modeGrid.querySelectorAll("[data-mode]").forEach(b=>b.onclick=()=>selectMode(b.dataset.mode,group))}
