function hostRoom(){if(!ensureName())return;destroyNet();isHost=true;room=mkcode();applyTheme(room);let tries=0;const go=()=>{if(typeof Peer==="undefined")return toast("Çevrimiçi bağlantı kütüphanesi yüklenemedi");peer=new Peer(hostPeerId(room),{debug:0});peer.on("open",id=>{me=id;S=blank();S.status="lobby";S.hostId=id;S.settings=settingsFor(selectedMode);S.players[id]=newPlayer(id,profile,true,false);render();startPingLoop()});peer.on("connection",c=>wireGuest(c));peer.on("error",e=>{if(e.type==="unavailable-id"&&tries++<4){try{peer.destroy()}catch{}room=mkcode();return setTimeout(go,120)}toast("Oda bağlantısı kurulamadı")})};go()}
function newPlayer(id,p,host=false,spectator=false){return{id,name:p.username||p.name||"Oyuncu",profileKey:p.profileKey||p.profile_key||"",rating:Number(p.rating)||1000,score:0,correct:0,wrong:0,streak:0,bestStreak:0,fastest:0,managerCorrect:0,host,active:true,ready:host,team:"A",spectator,eliminated:false,ping:0,ratingDelta:0,placement:0,joinedAt:Date.now()}}
function wireGuest(c){c.on("data",m=>guestMsg(c,m));c.on("close",()=>dropPlayer(c.peer));c.on("error",()=>dropPlayer(c.peer))}
function guestMsg(c,m){if(!m?.type)return;const x=m.payload||{};if(m.type==="join"){const n=cleanName(x.name),previousEntry=Object.entries(S.players).find(([id,p])=>p.profileKey&&p.profileKey===x.profileKey&&id!==S.hostId),previous=previousEntry?.[1],spectate=!!x.spectator||(S.status!=="lobby"&&!previous);if(!n)return send(c,"reject",{reason:"Geçersiz kullanıcı adı"});const duplicate=Object.values(S.players).find(p=>p.active!==false&&!p.spectator&&p.name.toLocaleLowerCase("tr")===n.toLocaleLowerCase("tr")&&p.profileKey!==x.profileKey);if(duplicate)return send(c,"reject",{reason:"Bu kullanıcı adı odada kullanılıyor."});if(!previous&&!spectate&&competitors().length>=S.settings.maxPlayers)return send(c,"reject",{reason:"Oyuncu kapasitesi dolu. Seyirci olarak katılabilirsin."});conns.set(c.peer,c);let p;if(previous){if(previousEntry[0]!==c.peer)delete S.players[previousEntry[0]];p={...previous,id:c.peer,name:n,profileKey:x.profileKey||previous.profileKey,rating:Number(x.rating)||previous.rating,active:true,host:false,ping:0,spectator:previous.spectator&&S.status!=="lobby"?true:spectate}}else{p=newPlayer(c.peer,{username:n,profileKey:x.profileKey,rating:x.rating},false,spectate);p.team=teamForNewPlayer()}S.players[c.peer]=p;send(c,"welcome",{playerId:c.peer,roomCode:room,state:snap()});sync();toast(n+(spectate?" seyirci oldu":previous?" yeniden bağlandı":" katıldı"))}else if(m.type==="select")choose(c.peer,x.optionId,x.roundId);else if(m.type==="ready"&&S.players[c.peer]){S.players[c.peer].ready=!!x.ready;sync()}else if(m.type==="latency"&&S.players[c.peer]){S.players[c.peer].ping=Math.max(0,Math.min(999,+x.ms||0));sync()}else if(m.type==="reaction"){const emoji=String(x.emoji||"");const allowed=["🔥","👏","⚽","🤯","😂","👍"];if(allowed.includes(emoji)){const name=S.players[c.peer]?.name||x.name||"Oyuncu";showReaction(name,emoji);conns.forEach((conn,id)=>{if(id!==c.peer)send(conn,"reaction",{name,emoji})})}}/*guestMsgReactionV5*/else if(m.type==="ping")send(c,"pong",{t:x.t})}
function teamForNewPlayer(){const a=competitors().filter(p=>p.team==="A").length,b=competitors().filter(p=>p.team==="B").length;return a<=b?"A":"B"}
function dropPlayer(id){conns.delete(id);if(!S.players[id])return;if(S.status==="lobby")delete S.players[id];else S.players[id].active=false;sync();checkSpent()}
function joinRoom(){if(!ensureName())return;const c=code(U.joinCode.value);if(c.length<4)return toast("Oda kodunu gir");destroyNet();isHost=false;room=c;applyTheme(room);connectAsGuest(!!U.spectatorJoin.checked)}
function connectAsGuest(spectator=false){if(typeof Peer==="undefined")return toast("Bağlantı kütüphanesi yüklenemedi");peer=new Peer(undefined,{debug:0});peer.on("open",id=>{me=id;openHostConnection(spectator)});peer.on("error",e=>{if(e.type==="peer-unavailable")toast("Oda bulunamadı");else toast("Bağlantı hatası")})}
function openHostConnection(spectator=false){hostConn=peer.connect(hostPeerId(room),{reliable:true});hostConn.on("open",()=>{send(hostConn,"join",{name:profile.username,profileKey:profile.profileKey,rating:profile.rating,spectator});connectionUI(true)});hostConn.on("data",hostMsg);hostConn.on("close",()=>{connectionUI(false);attemptReconnect(spectator)});hostConn.on("error",()=>connectionUI(false))}
let migrationBusy=false;
function migrationCandidate(){return Object.values(S.players).filter(p=>p.active!==false&&!p.spectator&&p.id!==S.hostId).sort((a,b)=>(a.joinedAt||0)-(b.joinedAt||0)||String(a.id).localeCompare(String(b.id)))[0]||null}
function promoteToHost(){if(isHost||migrationBusy)return false;const candidate=migrationCandidate();if(!candidate||candidate.id!==me)return false;migrationBusy=true;clearTimeout(reconnectTimer);const oldMe=me,oldHost=S.hostId,mine={...S.players[oldMe]};if(S.players[oldHost]){const departed={...S.players[oldHost],id:"departed-"+Date.now(),active:false,host:false};S.players[departed.id]=departed;delete S.players[oldHost]}delete S.players[oldMe];try{hostConn?.close()}catch{}hostConn=null;try{peer?.destroy()}catch{}peer=null;conns.clear();let attempts=0;const launch=()=>{attempts++;peer=new Peer(hostPeerId(room),{debug:0});peer.on("connection",c=>wireGuest(c));peer.on("open",id=>{me=id;isHost=true;S.hostId=id;S.players[id]={...mine,id,host:true,active:true,ready:true,ping:0};migrationBusy=false;connectionUI(true,0);if(S.status==="playing"){clearInterval(tickTimer);tickTimer=setInterval(()=>{if(isHost&&S.status==="playing"&&S.endsAt&&Date.now()>=S.endsAt)finishMatch("time")},200)}render();sync();toast("Kurucu ayrıldı • Yeni kurucu sensin")});peer.on("error",e=>{try{peer.destroy()}catch{}if(e.type==="unavailable-id"&&attempts<10)return setTimeout(launch,450);migrationBusy=false;toast("Oda devri tamamlanamadı")})};setTimeout(launch,350);return true}
function attemptReconnect(spectator){if(promoteToHost())return;let tries=0;clearTimeout(reconnectTimer);const retry=()=>{if(isHost||!peer||tries++>=10){if(!isHost)toast("Kurucu bağlantısı kesildi");return}if(promoteToHost())return;toast(`Yeniden bağlanılıyor ${tries}/10`);try{hostConn?.close()}catch{}hostConn=peer.connect(hostPeerId(room),{reliable:true});hostConn.on("open",()=>{send(hostConn,"join",{name:profile.username,profileKey:profile.profileKey,rating:profile.rating,spectator});connectionUI(true)});hostConn.on("data",hostMsg);hostConn.on("close",()=>{connectionUI(false);reconnectTimer=setTimeout(retry,800)});hostConn.on("error",()=>{connectionUI(false);reconnectTimer=setTimeout(retry,800)})};reconnectTimer=setTimeout(retry,650)}
function hostMsg(m){if(!m?.type)return;const x=m.payload||{};if(m.type==="reject"){toast(x.reason||"Giriş reddedildi");return}if(m.type==="welcome"){me=x.playerId;room=x.roomCode;Object.assign(S,x.state);render();startPingLoop()}else if(m.type==="state"){Object.assign(S,x);render()}else if(m.type==="kick"){toast("Odadan çıkarıldın");setTimeout(home,900)}else if(m.type==="pong"){const ms=Date.now()-x.t;send(hostConn,"latency",{ms});if(S.players[me])S.players[me].ping=ms;connectionUI(true,ms)}else if(m.type==="reaction"){showReaction(x.name,x.emoji)}else if(m.type==="result"){x.good?okSound():wrongSound()}/*hostMsgReactionV5*/}
function showReaction(name,emoji){const el=document.createElement("div");el.className="reaction-pop";el.innerHTML=`<b>${esc(name||"Oyuncu")}</b><span>${emoji}</span>`;document.body.appendChild(el);requestAnimationFrame(()=>el.classList.add("show"));setTimeout(()=>{el.classList.remove("show");setTimeout(()=>el.remove(),260)},1650)}
function sendReaction(emoji){const allowed=["🔥","👏","⚽","🤯","😂","👍"];if(!allowed.includes(emoji))return;const name=S.players[me]?.name||profile.username||"Oyuncu";showReaction(name,emoji);if(isHost)broadcast("reaction",{name,emoji});else send(hostConn,"reaction",{name,emoji})}
function startPingLoop(){clearInterval(pingTimer);pingTimer=setInterval(()=>{if(isHost){if(S.players[me])S.players[me].ping=0;conns.forEach(c=>send(c,"ping",{t:Date.now()}))}else if(hostConn?.open)send(hostConn,"ping",{t:Date.now()})},5000)}
function connectionUI(ok,ms){U.connectionDot.classList.toggle("online",!!ok);U.connectionText.textContent=ok?"Bağlantı aktif":"Bağlantı kesildi";U.pingText.textContent=ok?(typeof ms==="number"?`${Math.round(ms)} ms`:"Canlı senkronizasyon"):"Yeniden bağlanma bekleniyor"}
function startSolo(){if(!ensureName())return;destroyNet();isHost=true;room="SOLO";me="solo-"+profile.profileKey.slice(0,8);S=blank();S.status="lobby";S.hostId=me;S.settings=settingsFor(selectedMode);S.players[me]=newPlayer(me,profile,true,false);S.players[me].ready=true;applyTheme(profile.profileKey);startMatch()}
function applyMode(id){const max=S.settings.maxPlayers||8;S.settings={...settingsFor(id),maxPlayers:max};renderLobby();sync()}
function startMatch(){if(!isHost)return;if(competitors().length<1)return toast("En az 1 oyuncu gerekli");const m=mode();for(const p of Object.values(S.players)){p.score=0;p.correct=0;p.wrong=0;p.streak=0;p.bestStreak=0;p.fastest=0;p.managerCorrect=0;p.eliminated=false;p.ratingDelta=0;p.placement=0}S.status="playing";S.deck=makeDeck(S.settings.content);S.roundIndex=-1;S.cycle=0;S.matchId=uuid();S.matchStartedAt=Date.now();S.endsAt=S.settings.timeLimit?S.matchStartedAt+S.settings.timeLimit*1000:0;S.teamScores={A:0,B:0,coop:0};S.finishReason="";recordedMatch="";startMusic();clearInterval(tickTimer);tickTimer=setInterval(()=>{if(isHost&&S.status==="playing"&&S.endsAt&&Date.now()>=S.endsAt)finishMatch("time")},200);nextRound()}
function nextRound(){if(!isHost||S.status!=="playing")return;if(S.endsAt&&Date.now()>=S.endsAt)return finishMatch("time");const m=mode();if(!S.endsAt&&S.roundIndex+1>=S.settings.roundCount)return finishMatch("cards");S.roundIndex++;if(S.roundIndex>=S.deck.length){S.cycle++;S.deck=makeDeck(S.settings.content);S.roundIndex=0}const r=resolveDeckItem(S.deck[S.roundIndex]);if(!r)return finishMatch("data");S.currentRound=r;S.options=buildOptions(r,S.settings.optionCount);S.selections={};S.locked=false;S.winnerId=null;S.correctAnswerId=key(r.kind,r.answer);S.roundStartedAt=Date.now();preloadNext();sync()}
function preloadNext(){for(let n=1;n<=3;n++){let idx=S.roundIndex+n;if(idx>=S.deck.length)continue;const r=resolveDeckItem(S.deck[idx]);if(!r)continue;for(const tid of [r.teamA,r.teamB])preloadUrl(window.QF_IMAGES?.teams?.[tid]);const e=entity(r.kind,r.answer);preloadUrl(r.kind==="manager"?window.QF_MANAGER_IMAGES?.[e?.id]:window.QF_IMAGES?.players?.[e?.id])}}
const warmed=new Set();function preloadUrl(u){if(!u||warmed.has(u))return;warmed.add(u);const i=new Image();i.src=u}
function localChoose(k){if(S.status!=="playing"||S.locked||S.players[me]?.spectator||S.players[me]?.eliminated||S.selections[me])return;ensureAudio();isHost?choose(me,k,S.currentRound.id):send(hostConn,"select",{optionId:k,roundId:S.currentRound.id})}
function choose(pid,opt,rid){if(!isHost||S.status!=="playing"||S.locked||S.currentRound?.id!==rid||S.selections[pid]||!S.options.includes(opt))return;const p=S.players[pid];if(!p||p.active===false||p.spectator||p.eliminated)return;const cfg=mode(),good=opt===S.correctAnswerId,ms=Math.max(0,Date.now()-S.roundStartedAt);S.selections[pid]={optionId:opt,correct:good,ms};if(good){p.correct++;p.streak++;p.bestStreak=Math.max(p.bestStreak,p.streak);p.fastest=p.fastest?Math.min(p.fastest,ms):ms;if(S.currentRound.kind==="manager")p.managerCorrect++;const scoring=S.settings.scoring||cfg.scoring,pts=scoring==="streak"?1+Math.min(2,Math.floor((p.streak-1)/3)):1;if(S.settings.rule==="team"){p.score+=pts;S.teamScores[p.team]=(S.teamScores[p.team]||0)+pts}else if(S.settings.rule==="coop"){p.score+=pts;S.teamScores.coop+=pts}else p.score+=pts;S.locked=true;S.winnerId=pid;broadcast("result",{good:true,winnerId:pid,points:pts});sync();okSound();const target=+S.settings.targetScore||+cfg.targetScore||0,hit=target&&(S.settings.rule==="team"?S.teamScores[p.team]>=target:S.settings.rule==="coop"?S.teamScores.coop>=target:p.score>=target);if(hit)return setTimeout(()=>finishMatch("target"),S.settings.chill?900:550);return setTimeout(nextRound,S.settings.chill?1050:650)}p.wrong++;p.streak=0;if(S.settings.rule==="survival")p.eliminated=true;broadcast("result",{good:false,winnerId:null});wrongSound();if(S.settings.rule==="solo"||competitors().length===1){S.locked=true;sync();return setTimeout(nextRound,850)}sync();if(S.settings.rule==="survival"&&eligible().length<=1)return setTimeout(()=>finishMatch("survival"),700);checkSpent()}
function checkSpent(){if(!isHost||S.status!=="playing"||S.locked)return;const a=eligible();if(a.length&&a.every(p=>!!S.selections[p.id])){S.locked=true;sync();setTimeout(nextRound,S.settings.chill?1200:780)}}
function finishMatch(reason="complete"){if(!isHost||S.status==="final")return;clearInterval(tickTimer);S.status="final";S.finishReason=reason;S.locked=true;S.currentRound=null;S.options=[];const list=competitors().sort((a,b)=>b.score-a.score||b.correct-a.correct||a.wrong-b.wrong||a.name.localeCompare(b.name));let place=1,prev=null;list.forEach((p,i)=>{if(prev!==null&&p.score<prev)place=i+1;p.placement=place;prev=p.score});const top=list[0]?.score,topCount=list.filter(p=>p.score===top).length;for(const p of list)p.ratingDelta=ratingDelta(p,list,topCount);S.awards=buildAwards(list);sync();renderFinal()}
function ratingDelta(p,list,topCount){if(!S.settings.rated||list.length<2)return 0;if(topCount>1&&p.score===list[0].score)return 4;if(p.placement===1)return list.length>=4?28:24;if(p.placement===2&&list.length>=3)return 6;return-12}
function buildAwards(list){if(!list.length)return[];const fastest=[...list].filter(p=>p.fastest>0).sort((a,b)=>a.fastest-b.fastest)[0],streak=[...list].sort((a,b)=>b.bestStreak-a.bestStreak)[0],clean=[...list].sort((a,b)=>a.wrong-b.wrong||b.correct-a.correct)[0];return[{icon:"⚡",title:"En Hızlı",value:fastest?`${fastest.name} • ${(fastest.fastest/1000).toFixed(2)} sn`:"—"},{icon:"🔥",title:"En İyi Seri",value:streak?`${streak.name} • ${streak.bestStreak}`:"—"},{icon:"🎯",title:"En Temiz",value:clean?`${clean.name} • ${clean.wrong} yanlış`:"—"}]}
function render(){syncProfileUI();if(S.status==="lobby"){screen("lobby");renderLobby()}else if(S.status==="playing"){screen("game");renderGame()}else if(S.status==="final"){screen("final");renderFinal()}else{screen("home");renderHome()}U.sound.textContent=sound?"🔊":"🔇"}
function renderHome(){U.homeModeCount.textContent=Object.keys(MODES).length;const m=MODES[selectedMode]||MODES.classic25;U.selectedModeName.textContent=m.name;U.selectedModeDesc.textContent=m.desc;updateCloudChip()}
function renderLobby(){const m=mode();U.roomCode.textContent=room||"SOLO";U.lobbyModeTitle.textContent=m.icon+" "+m.name;U.lobbyModeDesc.textContent=m.desc;const all=Object.values(S.players).filter(p=>p.active!==false),players=all.filter(p=>!p.spectator),spec=all.filter(p=>p.spectator);U.lobbyCapacity.textContent=`${players.length} / ${S.settings.maxPlayers}`;U.spectatorInfo.textContent=spec.length?`${spec.length} seyirci bağlı`:"";U.lobbyPlayers.innerHTML=all.map(p=>`<div class="lobby-player ${p.id===me?"me-player":""}"><div class="player-meta"><div class="avatar-dot">${esc(initials(p.name))}</div><div><b>${esc(p.name)}</b><small>${p.spectator?"Seyirci":p.host?"Oda kurucusu":p.ready?"Hazır":"Hazırlanıyor"}</small></div></div><div class="player-side-actions">${p.spectator?'<span class="spectator-badge">SEYİRCİ</span>':`<span class="team-badge team-${p.team.toLowerCase()}">${p.team==="A"?"MAVİ":"ALTIN"}</span>${p.ready?'<span class="ready-badge">HAZIR</span>':""}`}<span class="ping-badge">${p.ping?Math.round(p.ping)+"ms":"●"}</span>${isHost&&!p.host?`<button class="kick-btn" data-kick="${esc(p.id)}">×</button>`:""}</div></div>`).join("");U.lobbyPlayers.querySelectorAll("[data-kick]").forEach(b=>b.onclick=()=>kick(b.dataset.kick));U.modeSelect.value=S.settings.modeId;U.choiceSelect.value=String(S.settings.optionCount);U.maxPlayers.value=String(S.settings.maxPlayers);U.contentSelect.value=S.settings.content;for(const e of [U.modeSelect,U.choiceSelect,U.maxPlayers,U.contentSelect])e.disabled=!isHost;U.start.style.display=isHost?"":"none";U.start.disabled=!isHost||players.length<1;U.ready.style.display=S.players[me]?.spectator?"none":"";U.ready.textContent=S.players[me]?.ready?"Hazırım ✓":"Hazırım";U.hostControl.textContent=isHost?"Kurucu kontrolü":"Kurucu belirliyor";U.format.textContent=formatText(S.settings);U.teamTools.classList.toggle("hidden",S.settings.rule!=="team");U.hostHint.textContent=isHost?`${players.length} oyuncu bağlı. Tek oyuncuyla da başlatabilirsin.`:"Kurucunun maçı başlatmasını bekliyorsun.";U.modeRules.innerHTML=ruleHtml({...m,...S.settings});syncCustomControls();connectionUI(isHost||hostConn?.open,S.players[me]?.ping||0)}
function formatText(s){const end=s.targetScore?`${s.targetScore} hedef puan`:s.timeLimit?`${Math.round(s.timeLimit/60)} dakika`:`${s.roundCount} kart`,score=s.scoring==="streak"?"seri bonusu":"normal puan";return`${end} • ${s.optionCount} seçenek • ${s.content==="manager"?"teknik direktör":s.content==="mixed"?"karma":"futbolcu"} • ${score}`}
function ruleHtml(m){const end=m.targetScore?`${m.targetScore} puana ilk ulaşan taraf maçı anında bitirir.`:m.timeLimit?`Maç ${Math.round(m.timeLimit/60)} dakika sonunda kart sayısından bağımsız biter.`:`Maç ${m.roundCount} kart sonunda biter.`,score=m.scoring==="streak"?"Seri uzadıkça doğru cevap 2–3 puana kadar çıkar.":m.rule==="survival"?"Yanlış seçim oyuncuyu eler.":m.rule==="team"?"İlk doğru cevap takım puanını artırır.":m.rule==="coop"?"Herkes ortak hedef için oynar.":"Competitive akışta ilk doğru cevap turu kazanır.";const arr=[m.rated?"Global rating bu maçtan etkilenir.":"Bu mod rating kaybettirmez.",end,score];return arr.map((x,i)=>`<div class="rule-row"><i>${["◈","⏱","⚡"][i]}</i><span>${esc(x)}</span></div>`).join("")}
function renderGame(){const r=S.currentRound;if(!r)return;const m=mode(),a=D.teams[r.teamA],b=D.teams[r.teamB],count=S.settings.optionCount,spent=!!S.selections[me],mine=S.players[me];U.gameModeIcon.textContent=m.icon;U.gameModeName.textContent=m.name;U.gameContent.textContent=r.kind==="manager"?"TEKNİK DİREKTÖR BAĞLANTISI":"FUTBOLCU BAĞLANTISI";U.questionType.textContent=r.kind==="manager"?"TEKNİK DİREKTÖR":"FUTBOLCU";U.optionChip.textContent=`${count} SEÇENEK`;U.relation.textContent=r.kind==="manager"?"İKİ KULÜBÜ DE ÇALIŞTIRDI":"İKİ KULÜPTE DE OYNADI";U.teamAName.textContent=a.short;U.teamBName.textContent=b.short;teamImage(U.teamALogo,r.teamA);teamImage(U.teamBLogo,r.teamB);U.roundProgress.textContent=S.endsAt?`#${S.roundIndex+1}`:`${S.roundIndex+1} / ${S.settings.roundCount}`;const progress=S.endsAt?Math.min(1,(Date.now()-S.matchStartedAt)/(S.settings.timeLimit*1000)):Math.min(1,(S.roundIndex+1)/S.settings.roundCount);U.progressBar.style.width=progress*100+"%";U.finalChip.classList.toggle("show",progress>=.82);U.roundStatus.textContent=S.locked?"Yeni soru hazırlanıyor":mine?.spectator?"Seyirci modundasın":mine?.eliminated?"Bu maçta elendin":spent?"Seçimini yaptın":r.kind==="manager"?"İki kulübü de çalıştırmış teknik direktörü seç":"İki kulüpte de oynamış futbolcuyu seç";renderAnswers(r,spent||mine?.spectator||mine?.eliminated);renderScores();renderFeed();renderPersonal();renderTimerUI()}
function renderAnswers(r,disabled){U.answerGrid.dataset.count=String(S.settings.optionCount);U.answerGrid.innerHTML=S.options.map((k,i)=>{const f=fromKey(k),e=entity(f.kind,f.id),mine=S.selections[me]?.optionId===k,correct=S.locked&&S.correctAnswerId===k,wrong=mine&&S.selections[me]&&!S.selections[me].correct;return`<button class="answer-card ${mine?"selected":""} ${correct?"correct revealed-correct":""} ${wrong?"wrong revealed-wrong":""}" data-answer="${k}" ${S.locked||disabled?"disabled":""}><span class="answer-index">${i+1}</span><div class="player-photo image-shell" data-kind="${f.kind}" data-id="${f.id}"><span>${esc(initials(e?.name))}</span></div><div class="answer-copy"><div class="answer-name">${esc(e?.name||"Bilinmiyor")}</div><div class="answer-sub">${f.kind==="manager"?"Teknik Direktör":"Futbolcu"}</div></div></button>`}).join("");U.answerGrid.querySelectorAll("[data-answer]").forEach(b=>b.onclick=()=>localChoose(b.dataset.answer));U.answerGrid.querySelectorAll(".player-photo").forEach(x=>personImage(x,x.dataset.kind,x.dataset.id));const answer=S.correctAnswerId?entity(fromKey(S.correctAnswerId).kind,fromKey(S.correctAnswerId).id):null;if(S.locked)U.result.textContent=S.winnerId?`${S.players[S.winnerId]?.name||"Oyuncu"} turu aldı • ${answer?.name||""}`:`Doğru cevap: ${answer?.name||""}`;else U.result.textContent=""}
function renderScores(){const list=competitors().sort((a,b)=>b.score-a.score||b.correct-a.correct);U.teamScoreText.textContent=S.settings.rule==="team"?`MAVİ ${S.teamScores.A} • ${S.teamScores.B} ALTIN`:S.settings.rule==="coop"?`ORTAK ${S.teamScores.coop}`:"";U.scorePlayers.innerHTML=list.map((p,i)=>`<div class="player-row ${p.eliminated?"eliminated":""} ${S.settings.rule==="team"?`score-player-team-${p.team.toLowerCase()}`:""}"><span class="rank">${i+1}</span><div class="score-name"><b>${esc(p.name)}</b><small>${p.eliminated?"ELENDİ":p.id===me?"SEN":p.team==="A"?"MAVİ":"ALTIN"}</small></div><div class="score-right">${p.streak>=2?`<span class="streak-chip">🔥${p.streak}</span>`:""}<strong>${p.score}</strong></div></div>`).join("")}
function renderFeed(){const rows=Object.entries(S.selections).map(([id,s])=>{const p=S.players[id],f=fromKey(s.optionId),e=entity(f.kind,f.id);return`<div class="feed-item ${s.correct?"correct-feed":""}"><span>${s.correct?"✓":"×"}</span><div><b>${esc(p?.name||"Oyuncu")}</b><small>${esc(e?.name||"")} • ${(s.ms/1000).toFixed(2)} sn</small></div></div>`});U.feed.innerHTML=rows.length?rows.join(""):'<div class="empty-feed">Henüz seçim yok.</div>'}
function renderPersonal(){const p=S.players[me];if(!p)return U.personalStats.innerHTML="";U.personalStats.innerHTML=`<div class="mini-stat"><b>${p.correct}</b><small>DOĞRU</small></div><div class="mini-stat"><b>${p.wrong}</b><small>YANLIŞ</small></div><div class="mini-stat"><b>${p.bestStreak}</b><small>EN İYİ SERİ</small></div><div class="mini-stat"><b>${p.fastest?`${(p.fastest/1000).toFixed(2)}s`:"—"}</b><small>EN HIZLI</small></div>`}
function renderTimerUI(){if(!S.endsAt){U.timerText.textContent="∞";U.timerBar.style.width="100%";U.matchClock.classList.remove("danger");return}const left=Math.max(0,S.endsAt-Date.now()),sec=Math.ceil(left/1000),m=Math.floor(sec/60),s=sec%60;U.timerText.textContent=`${m}:${String(s).padStart(2,"0")}`;const pct=Math.max(0,left/(S.settings.timeLimit*1000))*100;U.timerBar.style.width=pct+"%";U.matchClock.classList.toggle("danger",left<30000)}
function renderFinal(){screen("final");stopMusic();const list=competitors().sort((a,b)=>a.placement-b.placement||b.score-a.score),mine=S.players[me],m=mode();if(S.settings.rule==="team"){const win=S.teamScores.A===S.teamScores.B?"Beraberlik":S.teamScores.A>S.teamScores.B?"Mavi Takım Kazandı":"Altın Takım Kazandı";U.winnerTitle.textContent=win;U.winnerSubtitle.textContent=`Mavi ${S.teamScores.A} • ${S.teamScores.B} Altın`}else if(S.settings.rule==="coop"){U.winnerTitle.textContent="Ortak Görev Tamamlandı";U.winnerSubtitle.textContent=`Takımınız ${S.teamScores.coop} bağlantı buldu.`}else{U.winnerTitle.textContent=list.length===1?"Kişisel Sonucun":`${list[0]?.name||"Oyuncu"} Kazandı`;U.winnerSubtitle.textContent=`${m.name} • ${S.finishReason==="time"?"Süre tamamlandı":S.finishReason==="survival"?"Son oyuncu kaldı":"Maç tamamlandı"}`}U.finalScores.innerHTML=list.map(p=>`<div class="final-score-row"><span>#${p.placement}</span><b>${esc(p.name)}</b><small>${p.correct} doğru • ${p.wrong} yanlış • seri ${p.bestStreak}</small><strong>${p.score}</strong></div>`).join("");U.ratingResult.innerHTML=mine?`<div class="rating-chip ${mine.ratingDelta>0?"positive":mine.ratingDelta<0?"negative":""}"><small>RATING</small><b>${mine.ratingDelta>0?"+":""}${mine.ratingDelta}</b></div><div class="rating-chip"><small>MAÇ SKORU</small><b>${mine.score}</b></div>`:"";U.awards.innerHTML=(S.awards||[]).map(a=>`<div class="award-card"><span>${a.icon}</span><b>${esc(a.title)}</b><small>${esc(a.value)}</small></div>`).join("");recordMyResult()}
async function recordMyResult(){if(!S.matchId||recordedMatch===S.matchId)return;const p=S.players[me];if(!p||p.spectator)return;recordedMatch=S.matchId;const list=competitors(),top=list[0]?.score||0,tie=list.filter(x=>x.score===top).length>1,won=p.placement===1&&!tie,draw=p.placement===1&&tie,wasSolo=list.length===1,old={...profile};profile.games++;if(won)profile.wins++;else if(draw)profile.draws++;else profile.losses++;profile.correct+=p.correct;profile.wrong+=p.wrong;profile.bestStreak=Math.max(profile.bestStreak,p.bestStreak);profile.managerCorrect+=p.managerCorrect;if(S.settings.timeLimit)profile.timedBest=Math.max(profile.timedBest,p.score);if(wasSolo)profile.soloBest=Math.max(profile.soloBest,p.score);if(S.settings.rated&&won)profile.rankedWins++;if(S.settings.chill)profile.chillGames++;profile.rating=Math.max(100,profile.rating+p.ratingDelta);const xpGain=p.correct*10+(won?30:0)+Math.max(0,p.bestStreak-2)*3;profile.xp+=xpGain;profile.level=Math.max(1,Math.floor(Math.sqrt(profile.xp/120))+1);profile.badges=unlockBadges(profile,p,won,wasSolo);saveProfileLocal();const duration=Math.round(((S.endsAt?Math.min(Date.now(),S.endsAt):Date.now())-S.matchStartedAt)/1000);const h={at:Date.now(),mode:S.settings.modeId,modeName:mode().name,score:p.score,correct:p.correct,wrong:p.wrong,placement:p.placement,ratingDelta:p.ratingDelta};history.unshift(h);saveHistory();try{await window.QFCloud?.recordMatch?.({match_id:S.matchId,profile_key:profile.profileKey,username:profile.username,mode:S.settings.modeId,content_type:S.settings.content,placement:p.placement,score:p.score,correct:p.correct,wrong:p.wrong,best_streak:p.bestStreak,duration_sec:duration,rating_delta:p.ratingDelta,room_code:room,profile:{profile_key:profile.profileKey,username:profile.username,rating:profile.rating,xp:profile.xp,level:profile.level,games:profile.games,wins:profile.wins,losses:profile.losses,draws:profile.draws,correct:profile.correct,wrong:profile.wrong,best_streak:profile.bestStreak,timed_best:profile.timedBest,solo_best:profile.soloBest,ranked_wins:profile.rankedWins,chill_games:profile.chillGames,manager_correct:profile.managerCorrect,badges:profile.badges}})}catch{}if(old.rating!==profile.rating)syncProfileUI()}
function unlockBadges(p,s,won,solo){const b=new Set(p.badges||[]);if(p.games>=1)b.add("İlk Maç");if(won)b.add("Maç Galibi");if(p.wins>=10)b.add("10 Galibiyet");if(s.bestStreak>=5)b.add("Seri 5");if(s.bestStreak>=10)b.add("Seri 10");if(s.fastest&&s.fastest<1500)b.add("Şimşek");if(s.managerCorrect>=5)b.add("Taktik Dehası");if(solo&&s.score>=20)b.add("Solo 20");if(p.rating>=1200)b.add("1200 Kulübü");if(p.rating>=1500)b.add("Elite");return[...b]}
function kick(id){if(!isHost||!S.players[id])return;send(conns.get(id),"kick",{});try{conns.get(id)?.close()}catch{};delete S.players[id];conns.delete(id);sync()}
function toggleReady(){const p=S.players[me];if(!p||p.spectator)return;p.ready=!p.ready;if(isHost)sync();else send(hostConn,"ready",{ready:p.ready});renderLobby()}
function installCustomControls(){if(document.getElementById("customMatchControls")||!U.format)return;U.format.insertAdjacentHTML("beforebegin",`<div id="customMatchControls" class="custom-match-controls hidden"><div class="panel-label"><span>ÖZEL MAÇ LABORATUVARI</span><small>Yüzlerce kombinasyon</small></div><div class="custom-grid"><label>Bitiş<select id="customEnd"><option value="cards25">25 kart</option><option value="cards50">50 kart</option><option value="cards100">100 kart</option><option value="time180">3 dakika</option><option value="time300">5 dakika</option><option value="time600">10 dakika</option><option value="target10">10 hedef puan</option><option value="target20">20 hedef puan</option></select></label><label>Puanlama<select id="customScoring"><option value="normal">Normal +1</option><option value="streak">Seri bonusu +1/+2/+3</option></select></label><label>Kural<select id="customRule"><option value="first">Herkes tek</option><option value="team">Mavi vs Altın</option><option value="coop">Co-op ortak skor</option><option value="survival">Survival</option></select></label></div></div>`);for(const id of ["customEnd","customScoring","customRule"])document.getElementById(id).onchange=applyCustomControls}
function customEndValue(){if(S.settings.targetScore)return`target${S.settings.targetScore}`;if(S.settings.timeLimit)return`time${S.settings.timeLimit}`;return`cards${S.settings.roundCount}`}
function syncCustomControls(){const box=document.getElementById("customMatchControls");if(!box)return;const on=S.settings.modeId==="custom";box.classList.toggle("hidden",!on);for(const id of ["customEnd","customScoring","customRule"])if(document.getElementById(id))document.getElementById(id).disabled=!isHost;if(!on)return;document.getElementById("customEnd").value=customEndValue();document.getElementById("customScoring").value=S.settings.scoring||"normal";document.getElementById("customRule").value=S.settings.rule||"first"}
function applyCustomControls(){if(!isHost||S.settings.modeId!=="custom")return;const end=document.getElementById("customEnd")?.value||"cards25";S.settings.timeLimit=0;S.settings.targetScore=0;S.settings.roundCount=100;if(end.startsWith("cards"))S.settings.roundCount=+end.slice(5)||25;else if(end.startsWith("time"))S.settings.timeLimit=+end.slice(4)||180;else if(end.startsWith("target"))S.settings.targetScore=+end.slice(6)||10;S.settings.scoring=document.getElementById("customScoring")?.value==="streak"?"streak":"normal";const rule=document.getElementById("customRule")?.value;S.settings.rule=["first","team","coop","survival"].includes(rule)?rule:"first";S.settings.rated=false;sync()}
function changeSetting(e){if(!isHost)return;const id=U.modeSelect.value;if(id!==S.settings.modeId){const max=+U.maxPlayers.value||8;S.settings={...settingsFor(id),maxPlayers:max};U.choiceSelect.value=String(S.settings.optionCount);U.contentSelect.value=S.settings.content}else{S.settings.optionCount=[4,6,8].includes(+U.choiceSelect.value)?+U.choiceSelect.value:S.settings.optionCount;S.settings.content=["player","manager","mixed"].includes(U.contentSelect.value)?U.contentSelect.value:S.settings.content}S.settings.maxPlayers=Math.max(2,Math.min(8,+U.maxPlayers.value||8));sync()}
