function setImage(el,url,alt,cls){if(!el)return;if(!url){el.innerHTML=`<span>${esc(initials(alt))}</span>`;return}const img=new Image();img.alt=alt;img.decoding="async";img.loading="eager";img.className=cls;img.onload=()=>{el.innerHTML="";el.appendChild(img)};img.onerror=()=>{el.innerHTML=`<span>${esc(initials(alt))}</span>`};img.src=url}
function ensureAudio(){if(!sound)return null;if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==="suspended")audio.resume();return audio}
function tone(freq=.5,dur=.15,type="sine",gain=.025){const a=ensureAudio();if(!a)return;const o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(gain,a.currentTime);g.gain.exponentialRampToValueAtTime(.0001,a.currentTime+dur);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+dur)}
function okSound(){tone(660,.13,"sine",.025);setTimeout(()=>tone(880,.16,"sine",.02),70)}function wrongSound(){tone(170,.14,"triangle",.018)}
function startMusic(){if(!sound||music)return;const a=ensureAudio();if(!a)return;let step=0;const chords=[[110,164.81,220],[98,146.83,196],[123.47,185,246.94],[87.31,130.81,174.61]];const play=()=>{const now=a.currentTime;for(const f of chords[step++%chords.length]){const o=a.createOscillator(),g=a.createGain();o.type="sine";o.frequency.value=f;g.gain.setValueAtTime(.0001,now);g.gain.linearRampToValueAtTime(.009,now+.35);g.gain.exponentialRampToValueAtTime(.0001,now+3.4);o.connect(g);g.connect(a.destination);o.start(now);o.stop(now+3.5)}};play();music=setInterval(play,3300)}function stopMusic(){if(music)clearInterval(music);music=null}
function toggleSound(){sound=!sound;localStorage.setItem(SOUND_LS,sound?"1":"0");U.sound.textContent=sound?"🔊":"🔇";if(!sound)stopMusic();else if(S.status==="playing")startMusic()}
