function showProfile(){openModal(U.profileModal);U.profileModalName.textContent=profile.username||"Oyuncu";const acc=profile.correct+profile.wrong?Math.round(profile.correct/(profile.correct+profile.wrong)*100):0;const stats=[["Rating",Math.round(profile.rating)],["Seviye",profile.level],["Maç",profile.games],["Galibiyet",profile.wins],["Doğruluk",acc+"%"],["En iyi seri",profile.bestStreak],["Solo rekor",profile.soloBest],["Süreli rekor",profile.timedBest]];U.profileStats.innerHTML=stats.map(([a,b])=>`<div class="profile-stat"><b>${b}</b><small>${a.toUpperCase()}</small></div>`).join("");U.badgeGrid.innerHTML=profile.badges.length?profile.badges.map(b=>`<span class="profile-badge">✦ ${esc(b)}</span>`).join(""):'<small>Rozet kazanmak için maç oyna.</small>';U.historyList.innerHTML=history.length?history.slice(0,12).map(h=>`<div class="history-row"><span><b>${esc(h.modeName||h.mode)}</b><small> ${new Date(h.at).toLocaleDateString("tr-TR")}</small></span><span>#${h.placement} • ${h.score} puan</span><span>${h.ratingDelta>0?"+":""}${h.ratingDelta} RP</span></div>`).join(""):'<div class="empty-feed">Henüz maç geçmişi yok.</div>'}
