function wire(){installCustomControls();if(!document.getElementById("reactionBar")){const panel=document.querySelector(".activity-panel");if(panel){panel.insertAdjacentHTML("beforeend",`<div id="reactionBar" class="reaction-bar"><small>TEPKİ</small>${["🔥","👏","⚽","🤯","😂","👍"].map(e=>`<button type="button" data-react="${e}">${e}</button>`).join("")}</div>`);panel.querySelectorAll("[data-react]").forEach(b=>b.onclick=()=>sendReaction(b.dataset.react))}}syncProfileUI();populateModeSelect();renderModeTabs((MODES[selectedMode]||MODES.classic25).group);selectMode(selectedMode);U.saveProfile.onclick=saveName;U.profileNameInput.onkeydown=e=>{if(e.key==="Enter")saveName()};U.createRoom.onclick=hostRoom;U.soloStart.onclick=startSolo;U.joinRoom.onclick=joinRoom;U.joinCode.onkeydown=e=>{if(e.key==="Enter")joinRoom()};document.querySelectorAll(".mode-tab").forEach(b=>b.onclick=()=>renderModeTabs(b.dataset.group));U.modeSelect.onchange=changeSetting;U.choiceSelect.onchange=changeSetting;U.maxPlayers.onchange=changeSetting;U.contentSelect.onchange=changeSetting;U.start.onclick=startMatch;U.ready.onclick=toggleReady;U.copyRoom.onclick=copyInvite;U.qrRoom.onclick=showQR;U.sound.onclick=toggleSound;U.fullscreen.onclick=toggleFullscreen;U.brand.onclick=home;U.back.onclick=home;U.again.onclick=rematch;U.leaderboardBtn.onclick=()=>showLeaderboard("rating");U.leaderboardFinalBtn.onclick=()=>showLeaderboard("rating");U.profileBtn.onclick=showProfile;U.profilePill.onclick=showProfile;document.querySelectorAll("[data-close-modal]").forEach(b=>b.onclick=closeModal);U.backdrop.onclick=e=>{if(e.target===U.backdrop)closeModal()};document.querySelectorAll("[data-board]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-board]").forEach(x=>x.classList.toggle("active",x===b));showLeaderboard(b.dataset.board)});document.addEventListener("keydown",e=>{if(S.status==="playing"&&/^[1-8]$/.test(e.key)){const i=+e.key-1;if(S.options[i])localChoose(S.options[i])}if(e.key==="Escape")closeModal()});window.addEventListener("beforeunload",()=>{try{destroyNet()}catch{}});renderTimer=setInterval(()=>{if(S.status==="playing")renderTimerUI();updateCloudChip()},250);const q=new URLSearchParams(location.search).get("room");if(q){U.joinCode.value=code(q);if(profile.username)setTimeout(()=>joinRoom(),250)}if(profile.username)window.QFCloud?.ensureProfile?.({profile_key:profile.profileKey,username:profile.username,rating:profile.rating,xp:profile.xp,level:profile.level,games:profile.games,wins:profile.wins,losses:profile.losses,draws:profile.draws,correct:profile.correct,wrong:profile.wrong,best_streak:profile.bestStreak,timed_best:profile.timedBest,solo_best:profile.soloBest,ranked_wins:profile.rankedWins,chill_games:profile.chillGames,manager_correct:profile.managerCorrect,badges:profile.badges});renderHome()}
